function main({response}){
    var flag = false;
    var jwt = "";
    var errorMsg = "";

    try {
        var dataJson = JSON.parse(response);
        if(dataJson.result && dataJson.code == 200) {
            jwt = dataJson.data;
            flag = true;
        } else {
            errorMsg = "获取盖亚JWT权限失败，message=" + dataJson.message;
            flag = false;
        }
    } catch(e) {
        flag = false;
        errorMsg = "获取盖亚JWT权限失败，JSON格式错误，json=" + response;
    }

    return {
        flag: flag,
        jwt: jwt,
        errorMsg: errorMsg
    }

}

// 获取盖亚 JWT 权限
function main({response, typeName}){
    var flag = false;
    var errorMsg = "";
    var summarys = [];
    var result = {
        typeName: typeName,
        summary: "",
        detail: []
    };

    try {
        var dataJson = JSON.parse(response);
        if(dataJson.code == 200) {
            flag = true;
            if(!dataJson.details) {
                errorMsg = "没有找到假期余额数据";
            } else {
                var employeeData = dataJson.details && dataJson.details.employeeData;
                var employeeDetailData = employeeData[0].employeeDetailData;
                if((employeeDetailData instanceof Array) && employeeDetailData.length > 0) {
                    for(var i = 0; i < employeeDetailData.length; i++) {
                        var detailItem = employeeDetailData[i] || {};
                        var effectiveYear = detailItem.effectiveYear; // 归属年，格式：yyyy
                        var leaveCode = detailItem.leaveCode; // 假别code
                        var leaveName = detailItem.leaveName; // 假别名称
                        var leaveUsed = detailItem.leaveUsed || 0; // 已使用数量
                        var leaveTotal = detailItem.leaveTotal || 0; // 总额度
                        var leaveRemain = detailItem.leaveRemain || 0; // 剩余数量
                        var leaveApproving = detailItem.leaveApproving || 0; // 审批中数量
                        var leaveUnit = detailItem.leaveUnit; // 假别单位 0：天，1：小时

                        // 年假 A31
                        if(leaveCode == "A31") {
                            var details = detailItem.details || [];
                            var a31Datas = {};
                            var effectiveYears = [];
                            for(var j = 0; j < details.length; j++) {
                                var item = details[j] || {};
                                var effectiveYear = item.effectiveYear; // 归属年，格式：yyyy
                                var leaveDetailUsed = item.leaveDetailUsed || 0; // 已用数量
                                var leaveDetailTotal = item.leaveDetailTotal || 0; // 额度
                                var leaveDetailRemain = item.leaveDetailRemain || 0; // 剩余额度
                                var leaveDetailUnit = item.leaveDetailUnit; //假别单位 0：天，1：小时
                                var leaveDetailApproving = item.leaveDetailApproving || 0; //审批中数量

                                var tmpData = a31Datas[effectiveYear] || {
                                    effectiveYear: '',
                                    leaveDetailUsed: 0,
                                    leaveDetailTotal: 0,
                                    leaveDetailRemain: 0,
                                    leaveDetailApproving: 0
                                };
                                tmpData.effectiveYear = effectiveYear;
                                tmpData.leaveDetailUsed += leaveDetailUsed;
                                tmpData.leaveDetailTotal += leaveDetailTotal;
                                tmpData.leaveDetailRemain += leaveDetailRemain;
                                tmpData.leaveDetailApproving += leaveDetailApproving;
                                a31Datas[effectiveYear] = tmpData;

                                if(!effectiveYears.includes(effectiveYear * 1)) {
                                    effectiveYears.push(effectiveYear * 1);
                                }
                            }

                            for(var k = 0; k < effectiveYears.length; k++) {
                                var year = effectiveYears[k] || "";
                                var tmp = a31Datas[year] || {};
                                result.detail.push({
                                    effectiveYear: year,
                                    leaveCode: leaveCode,
                                    leaveName: year + "年假",
                                    leaveUnit: leaveDetailUnit,
                                    leaveRemain: tmp.leaveDetailRemain.toFixed(1),
                                    leaveTotal: tmp.leaveDetailTotal.toFixed(1),
                                    leaveUsed: tmp.leaveDetailUsed.toFixed(1),
                                    freeze: tmp.leaveDetailApproving.toFixed(1)
                                });
                            }
                        } else {
                            result.detail.push({
                                effectiveYear: effectiveYear,
                                leaveCode: leaveCode,
                                leaveName: "A47" == leaveCode ? "育儿假" : leaveName,
                                leaveUnit: leaveUnit,
                                leaveRemain: leaveRemain.toFixed(1),
                                leaveTotal: leaveTotal.toFixed(1),
                                leaveUsed: leaveUsed.toFixed(1),
                                freeze: leaveApproving.toFixed(1)
                            });
                        }
                    }
                }

                // 拼接描述
                /*for(var m = 0; m < result.detail.length; m++) {
                    var tdetail = result.detail[m] || {};
                    summarys.push(tdetail.leaveName + "剩余" + tdetail.leaveRemain + 
                        (tdetail.leaveUnit == 1 ? "小时" : "天"));
                }*/
                result.summary = "哆啦小贴士✨  您的假期余额如下："; // + summarys.join("；") + "。";
            }
        } else {
            errorMsg = "获取假期余额失败，message=" + dataJson.message;
            flag = false;
        }
    } catch(e) {
        console.log(e)
        flag = false;
        errorMsg = "获取假期余额失败，JSON格式错误，json=" + response;
    }

    return JSON.stringify({
        businessType: "leave_balance",
        flag: flag,
        errorMsg: errorMsg,
        data: result
    });
}

